<?php
declare(strict_types=1);
function commercialRead(string $key):?array{$r=one('SELECT value FROM tr_meta WHERE id=?',[$key]);return $r?json_decode(unseal($r['value']),true,64,JSON_THROW_ON_ERROR):null;}
function commercialWrite(string $key,array $v):void{$raw=j($v);if(strlen($raw)>42000)throw new Fault('O conteúdo excede o tamanho permitido. Reduza os textos ou a quantidade de itens.');$value=seal($raw);if(one('SELECT id FROM tr_meta WHERE id=?',[$key]))query('UPDATE tr_meta SET value=? WHERE id=?',[$value,$key]);else query('INSERT INTO tr_meta(id,value) VALUES(?,?)',[$key,$value]);}
function commercialContent(bool $draft=false):array{return commercialRead($draft?'site:draft':'site:published')??commercialRead('site:published')??json_decode(file_get_contents(TR_RELEASE.'/data/commercial-default.json'),true);}
function commercialLock():void{if(db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql')query('SELECT id FROM tr_meta WHERE id=? FOR UPDATE',['schema']);}
function commercialImageAllowed(string $value):bool{return $value===''||$value==='/workspace/logo-trajetoria.png'||preg_match('#^/commercial/screenshots/[a-z0-9-]+\.(png|jpg|webp)$#D',$value)&&is_file(TR_RELEASE.'/assets'.$value)||preg_match('/^image:[a-f0-9]{32}$/D',$value)&&commercialRead('site-image:'.substr($value,6));}
function commercialValidate(array $b):array{$out=[];foreach(['brand'=>60,'tagline'=>120,'title'=>160,'description'=>500,'footer'=>300] as $k=>$max)$out[$k]=need($b[$k]??'',['brand'=>'nome da marca','tagline'=>'descrição da marca','title'=>'título da página','description'=>'descrição da página','footer'=>'rodapé'][$k],$max);$out['logo']=$b['logo']??'/workspace/logo-trajetoria.png';if(!commercialImageAllowed($out['logo']))throw new Fault('Logo inválido.');$out['color']=$b['color']??'';if(!preg_match('/^#[a-fA-F0-9]{6}$/D',$out['color']))throw new Fault('Cor principal inválida.');$sections=$b['sections']??[];if(!$sections||count($sections)>24)throw new Fault('Use de 1 a 24 seções.');$ids=[];$out['sections']=[];
 foreach($sections as $s){$id=need($s['id']??'','identificador da seção',50);if(!preg_match('/^[a-z][a-z0-9-]*$/D',$id)||isset($ids[$id]))throw new Fault('Identificador de seção inválido ou duplicado.');$ids[$id]=true;$type=$s['type']??'';if(!in_array($type,['hero','benefits','features','showcase','steps','faq','contact','text']))throw new Fault('Tipo de seção inválido.');$row=['id'=>$id,'type'=>$type,'enabled'=>(bool)($s['enabled']??true)];foreach(['eyebrow'=>120,'title'=>200,'body'=>1800,'buttonLabel'=>80,'buttonHref'=>500,'image'=>250] as $key=>$max){$v=(string)($s[$key]??'');if(mb_strlen($v)>$max)throw new Fault('Texto muito longo na seção '.$id.'.');$row[$key]=$v;}if(!$row['title'])throw new Fault('Informe o título das seções.');$url=$row['buttonHref'];if($url&&!preg_match('#^(?:\#[a-z][a-z0-9-]*|https://[^\s<>"\x27]+|mailto:[a-zA-Z0-9.!%+_-]+@[a-zA-Z0-9.-]+|tel:\+?[0-9()-]+)$#D',$url))throw new Fault('Link do botão inválido.');if(!commercialImageAllowed($row['image']))throw new Fault('Selecione uma imagem da biblioteca do site.');$row['items']=[];if(count($s['items']??[])>12)throw new Fault('Use até 12 itens por seção.');foreach($s['items']??[] as $i){$item=['title'=>need($i['title']??'','título do item',160),'body'=>(string)($i['body']??''),'image'=>(string)($i['image']??'')];if(mb_strlen($item['body'])>1400||!commercialImageAllowed($item['image']))throw new Fault('Texto ou imagem de item inválido.');$row['items'][]=$item;}$out['sections'][]=$row;}
 if(count(array_filter($out['sections'],fn($s)=>$s['enabled']))===0)throw new Fault('Mantenha pelo menos uma seção visível.');return $out;}
function commercialApi(array $u,string $method,array $b):array{platformOwner($u);if($method==='GET')return ['content'=>commercialContent(true),'revision'=>(int)(one('SELECT value FROM tr_meta WHERE id=?',['site:revision'])['value']??0),'publishedAt'=>commercialRead('site:publication')['at']??null,'assets'=>commercialAssets()];if($method!=='POST')throw new Fault('Método não permitido.',405);if(($b['action']??'')==='upload')return commercialUpload($b);
 return txn(function()use($u,$b){commercialLock();$rev=(int)(one('SELECT value FROM tr_meta WHERE id=?',['site:revision'])['value']??0);if($rev!==($b['revision']??null))throw new Fault('O site foi alterado em outra sessão. Recarregue o editor antes de salvar.',409);$content=commercialValidate($b['content']??[]);$action=$b['action']??'';if(!in_array($action,['save','publish']))throw new Fault('Ação do editor inválida.');commercialWrite('site:draft',$content);if($action==='publish'){commercialWrite('site:previous',commercialContent());commercialWrite('site:published',$content);commercialWrite('site:publication',['at'=>date(DATE_ATOM),'actor'=>$u['id']]);}if(one('SELECT id FROM tr_meta WHERE id=?',['site:revision']))query('UPDATE tr_meta SET value=? WHERE id=?',[(string)($rev+1),'site:revision']);else query('INSERT INTO tr_meta(id,value) VALUES(?,?)',['site:revision','1']);audit('SYSTEM','site.'.$action,'commercial');return ['ok'=>true,'revision'=>$rev+1];});}
function commercialAssets():array{$assets=[['value'=>'/workspace/logo-trajetoria.png','label'=>'Logo original do Trajetória']];foreach(glob(TR_RELEASE.'/assets/commercial/screenshots/*')?:[] as $p)$assets[]=['value'=>'/commercial/screenshots/'.basename($p),'label'=>'Tela demonstrativa · '.pathinfo($p,PATHINFO_FILENAME)];foreach(query('SELECT id,value FROM tr_meta WHERE id LIKE ?',['site-image:%'])->fetchAll() as $r){$m=json_decode(unseal($r['value']),true);$assets[]=['value'=>'image:'.$m['id'],'label'=>$m['name']];}return $assets;}
function commercialUpload(array $b):array{$data=$b['image']??'';if(!is_string($data)||!preg_match('#^data:image/(jpeg|png|webp);base64,([A-Za-z0-9+/=]+)$#D',$data,$m))throw new Fault('Envie JPG, PNG ou WebP.');$bytes=base64_decode($m[2],true);$info=$bytes===false?false:@getimagesizefromstring($bytes);if(!$info||strlen($bytes)>750000||$info[0]*$info[1]>6000000||$info['mime']!=='image/'.$m[1])throw new Fault('Imagem inválida ou muito grande. Reduza para até 750 KB e 6 megapixels.');$id=uid();$file=TR_PRIVATE.'/data/site-'.$id.'.enc';if(file_put_contents($file,seal($bytes),LOCK_EX)===false)throw new Fault('Não foi possível gravar a imagem. Confira as permissões da pasta privada.',500);@chmod($file,0600);try{commercialWrite('site-image:'.$id,['id'=>$id,'mime'=>$info['mime'],'name'=>need($b['name']??'Imagem do site','nome da imagem',120)]);}catch(Throwable $e){@unlink($file);throw $e;}return ['asset'=>['value'=>'image:'.$id,'label'=>$b['name']??'Imagem do site']];}
function commercialImageUrl(string $image):string{return str_starts_with($image,'image:')?'/site-media/'.substr($image,6):$image;}
function commercialServeImage(string $id):never{$content=commercialContent();$used=false;foreach($content['sections'] as $s)if($s['enabled']){if(($s['image']??'')==='image:'.$id)$used=true;foreach($s['items']??[] as $item)if(($item['image']??'')==='image:'.$id)$used=true;}if(!$used)platformOwner(auth());$meta=commercialRead('site-image:'.$id);$file=TR_PRIVATE.'/data/site-'.$id.'.enc';if(!$meta||!is_file($file))throw new Fault('Imagem não encontrada.',404);header('Content-Type: '.$meta['mime']);header('X-Content-Type-Options: nosniff');echo unseal(file_get_contents($file));exit;}
function commercialLead(array $b):array{if(!array_filter(commercialContent()['sections'],fn($s)=>$s['enabled']&&$s['type']==='contact'))throw new Fault('Formulário indisponível.',404);if(trim((string)($b['website']??'')))return ['ok'=>true];$name=need($b['name']??'','nome',120);$email=mb_strtolower(need($b['email']??'','e-mail',190));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Fault('E-mail inválido.');$city=need($b['municipality']??'','município / órgão',150);$message=need($b['message']??'','mensagem',2000);$phone=trim((string)($b['phone']??''));$role=trim((string)($b['role']??''));if(strlen($phone)>30||$phone&&!preg_match('/^[0-9+() .-]+$/',$phone)||mb_strlen($role)>100)throw new Fault('Telefone ou função inválidos.');if(($b['consent']??false)!==true)throw new Fault('Confirme a autorização para retorno sobre esta solicitação.');return txn(function()use($name,$email,$city,$message,$phone,$role){commercialLock();$key=hash_hmac('sha256','contact:'.($_SERVER['REMOTE_ADDR']??'local'),config()['key']);$r=one('SELECT * FROM tr_login WHERE id=?',[$key]);if($r&&(int)$r['until_at']>time()&&(int)$r['count']>=5)throw new Fault('Limite de mensagens atingido. Tente mais tarde.',429);if(!$r)query('INSERT INTO tr_login(id,count,until_at) VALUES(?,?,?)',[$key,1,time()+3600]);else query('UPDATE tr_login SET count=?,until_at=? WHERE id=?',[(int)$r['until_at']<time()?1:(int)$r['count']+1,time()+3600,$key]);$id=uid();commercialWrite('site-lead:'.$id,['id'=>$id,'name'=>$name,'email'=>$email,'municipality'=>$city,'message'=>$message,'phone'=>$phone,'role'=>$role,'consentAt'=>date(DATE_ATOM),'created'=>date(DATE_ATOM),'state'=>'new','notes'=>'','version'=>1]);return ['ok'=>true];});}
function commercialLeadsApi(array $u,string $method,array $b):array{platformOwner($u);if($method==='GET'){$rows=[];foreach(query('SELECT value FROM tr_meta WHERE id LIKE ?',['site-lead:%'])->fetchAll() as $r)$rows[]=json_decode(unseal($r['value']),true);usort($rows,fn($a,$b)=>strcmp($b['created'],$a['created']));return ['rows'=>$rows];}if($method!=='POST')throw new Fault('Método não permitido.',405);return txn(function()use($u,$b){commercialLock();$id=need($b['id']??'','contato',32);if(!preg_match('/^[a-f0-9]{32}$/D',$id))throw new Fault('Contato inválido.');$lead=commercialRead('site-lead:'.$id);if(!$lead)throw new Fault('Contato não encontrado.',404);if($lead['version']!==($b['version']??null))throw new Fault('Contato alterado por outra sessão.',409);if(!in_array($b['state']??'',['new','contacted','closed']))throw new Fault('Situação inválida.');$notes=(string)($b['notes']??'');if(mb_strlen($notes)>2000)throw new Fault('Anotação muito longa.');$lead['state']=$b['state'];$lead['notes']=$notes;$lead['version']++;$lead['updated']=date(DATE_ATOM);commercialWrite('site-lead:'.$id,$lead);audit('SYSTEM','site.contact.update',$id);return ['ok'=>true];});}
